package it.carmine.streamplayer.lab211;
import java.net.*;import java.util.*;import java.util.regex.*;
/** Independently implemented adapters for the public GuardaFlix/GuardaSerie layouts. */
public final class ItalianCatalog implements LabPipeline.CatalogAdapter {
 private final boolean series;public ItalianCatalog(boolean series){this.series=series;}
 public String name(){return series?"GuardaSerie · catalogo":"GuardaFlix · catalogo";}
 public String search(String base,String query)throws Exception{return LabPipeline.origin(base)+(query.isEmpty()?series?"/serie/":"/":"/?s="+URLEncoder.encode(query,"UTF-8"));}
 public List<LabPipeline.Title> titles(LabPipeline.Page page){List<LabPipeline.Title> out=new ArrayList<>();String html=page.text();Pattern blocks=series?Pattern.compile("(?is)<div\\b[^>]*class=[\"'][^\"']*\\bml-item\\b[^\"']*[\"'][^>]*>(.*?)(?=<div\\b[^>]*class=[\"'][^\"']*\\bml-item\\b|$)"):Pattern.compile("(?is)<li\\b[^>]*>(.*?)</li>");Matcher b=blocks.matcher(html);Set<String> seen=new HashSet<>();while(b.find()&&out.size()<100){String card=b.group(1);Matcher img=Pattern.compile("(?is)<img\\b[^>]*>").matcher(card),a=Pattern.compile("(?is)<a\\b[^>]*>").matcher(card);if(!img.find())continue;Map<String,String> image=LabPipeline.attrs(img.group());String poster=LabPipeline.absolute(page.url,first(image,"data-src","data-original","src"));String url="",title="";while(a.find()){Map<String,String> link=LabPipeline.attrs(a.group());String c=LabPipeline.absolute(page.url,link.getOrDefault("href",""));if(!c.isEmpty()&&LabPipeline.host(c).equals(LabPipeline.host(page.url))){url=c;title=link.getOrDefault("title","");break;}}Matcher heading=Pattern.compile("(?is)<h[1-3]\\b[^>]*>(.*?)</h[1-3]>").matcher(card);if(heading.find())title=LabPipeline.decode(heading.group(1).replaceAll("<[^>]*>"," ").trim());if(title.isEmpty())title=image.getOrDefault("alt","");if(!url.isEmpty()&&!poster.isEmpty()&&!title.isEmpty()&&seen.add(url))out.add(new LabPipeline.Title(title,poster,url));}return out;}
 public List<LabPipeline.Source> sources(LabPipeline.Page page){List<LabPipeline.Source> out=new ArrayList<>();String html=page.text();Matcher area=Pattern.compile("(?is)<div\\b[^>]*id=[\"'](?:aa-options|player2)[\"'][^>]*>(.*?)(?=<(?:footer|section)\\b|$)").matcher(html);if(area.find())out.addAll(LabPipeline.declaredSources(new LabPipeline.Page(page.url,page.status,page.type,area.group(1).getBytes(java.nio.charset.StandardCharsets.UTF_8))));if(!out.isEmpty())return out;
 if(series){Matcher a=Pattern.compile("(?is)<a\\b([^>]*)>(.*?)</a>").matcher(html);while(a.find()){Map<String,String> at=LabPipeline.attrs(a.group(1));String label=LabPipeline.decode(a.group(2).replaceAll("<[^>]*>"," ").trim());if(!label.matches("(?i).*(?:[0-9]{1,2}x[0-9]{1,3}|episodio\\s*[0-9]+).*"))continue;String u=LabPipeline.absolute(page.url,at.getOrDefault("href",""));if(!u.isEmpty()&&LabPipeline.host(u).equals(LabPipeline.host(page.url)))out.add(new LabPipeline.Source(u,label,page.url));}}
 return out;}
 private static String first(Map<String,String> map,String... keys){for(String k:keys){String v=map.get(k);if(v!=null&&!v.isEmpty())return v;}return "";}
}
